// src/App.js
import React, { useState, useEffect } from 'react';
import GlobalStyle from './styles/GlobalStyle';
import styled from 'styled-components';
import axios from 'axios'; // Import Axios

import Header from './components/Header';
import Equipment from './components/Equipment';
import EquipmentSearch from './components/EquipmentSearch';
import SelectedSidebar from './components/SelectedSidebar';
import TrainingTips from './components/TrainingTips';
import { trainingTipsData } from './data/trainingTipsData';

const MainContainer = styled.div`
  display: flex;
  justify-content: space-between;
  margin: 20px auto;
  max-width: 1200px;
`;

const ContentArea = styled.div`
  flex: 2;
  padding-right: 20px;
`;

const SidebarArea = styled.div`
  flex: 1;
  padding-left: 20px;
`;

function App() {
  const [equipmentData, setEquipmentData] = useState([]); // All equipment data
  const [filteredEquipment, setFilteredEquipment] = useState([]); // Filtered data
  const [selectedEquipment, setSelectedEquipment] = useState([]);

  // Fetch equipment data using Axios
  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await axios.get('/api/competitivecyclist');

        // Flatten the nested object into a single array
        const rawData = response.data;

        const flattenedData = Object.values(rawData).flatMap(category =>
          Object.values(category).flat()
        );


        setEquipmentData(flattenedData);
        setFilteredEquipment(flattenedData); // Initialize filtered state
      } catch (error) {
        console.error('Error fetching data:', error.message);
      }
    };

    fetchData();
  }, []);

  // Handle search input and filter the equipment list
  const handleSearch = (searchTerm) => {
    if (searchTerm === '') {
      setFilteredEquipment(equipmentData); // Reset to full data if search is empty
    } else {
      const filtered = equipmentData.filter((item) =>
        item.Name.toLowerCase().includes(searchTerm.toLowerCase())
      );
      setFilteredEquipment(filtered);
    }
  };

  // Handle selecting an equipment item
  const handleSelect = (item) => {
    const itemWithPrice = { ...item, price: item.price || '$100' };
    setSelectedEquipment((prev) =>
      prev.find((i) => i.id === itemWithPrice.id)
        ? prev.filter((i) => i.id !== itemWithPrice.id) // Remove if already selected
        : [...prev, itemWithPrice] // Add if not selected
    );
  };

  const handleRemoveItem = (id) => {
    setSelectedEquipment(selectedEquipment.filter((item) => item.id !== id));
  };

  return (
    <>
      <GlobalStyle />
      <Header />

      <MainContainer>
        <ContentArea>
          <EquipmentSearch onSearch={handleSearch} />
          <Equipment equipment={filteredEquipment} handleSelect={handleSelect} />
          <TrainingTips tips={trainingTipsData} />
        </ContentArea>

        <SidebarArea>
          <SelectedSidebar selectedItems={selectedEquipment} removeItem={handleRemoveItem} />
        </SidebarArea>
      </MainContainer>
    </>
  );
}

export default App;
